// Calibration generated by calibrate.py
float hard_iron_bias_x = 41.1688664383;
float hard_iron_bias_y = -89.8746574012;
float hard_iron_bias_z = 569.66392945;

double soft_iron_bias_xx = 2.71193763188;
double soft_iron_bias_xy = 0.0278249273751;
double soft_iron_bias_xz = -0.113831458699;

double soft_iron_bias_yx = 0.0278249273751;
double soft_iron_bias_yy = 2.75088373849;
double soft_iron_bias_yz = 0.0297242096163;

double soft_iron_bias_zx = -0.113831458699;
double soft_iron_bias_zy = 0.0297242096163;
double soft_iron_bias_zz = 3.35796778919;

// get values x,y,z and subtract the hard iron offset
float xm_off = id(hmc5883l_x).state - hard_iron_bias_x;
float ym_off = id(hmc5883l_y).state - hard_iron_bias_y;
float zm_off = id(hmc5883l_z).state - hard_iron_bias_z;

// multiply by the inverse soft iron offset
float xm_cal = xm_off * soft_iron_bias_xx + ym_off * soft_iron_bias_yx + zm_off * soft_iron_bias_zx;
float ym_cal = xm_off * soft_iron_bias_xy + ym_off * soft_iron_bias_yy + zm_off * soft_iron_bias_zy;

float heading = atan2(0 - xm_cal, ym_cal);
if (heading < 0) { heading += 2*PI; }
if (heading > 2*PI) { heading -= 2*PI; }
return heading * 180/M_PI;

